import{_ as n,o as e,c as t,a2 as i}from"./chunks/framework.DBU8LMUS.js";const h=JSON.parse('{"title":"Program Mentoring","description":"","frontmatter":{"title":"Program Mentoring","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/mentoring.md","filePath":"latest/mentoring.md","lastUpdated":1786334463000}'),r={name:"latest/mentoring.md"};function l(o,a,m,s,u,g){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="program-mentoring" tabindex="-1">Program Mentoring <a class="header-anchor" href="#program-mentoring" aria-label="Permalink to &quot;Program Mentoring&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p><strong>Program Mentoring</strong> menghubungkan alumni yang berpengalaman (mentor) dengan alumni lain yang membutuhkan bimbingan (mentee). Modul ini menjelaskan cara mendaftar sebagai mentor, mengajukan permintaan mentoring, dan mengikuti alur status permintaan.</p><h2 id="melihat-daftar-mentor" tabindex="-1">Melihat Daftar Mentor <a class="header-anchor" href="#melihat-daftar-mentor" aria-label="Permalink to &quot;Melihat Daftar Mentor&quot;">​</a></h2><ol><li>Klik menu <strong>Mentoring</strong> pada navigasi.</li><li>Halaman menampilkan daftar mentor dengan informasi: <ul><li>Nama, pekerjaan, dan perusahaan.</li><li>Bidang keahlian yang dapat dibimbing.</li><li>Jumlah slot (kapasitas) mentee yang tersedia.</li></ul></li><li>Klik kartu mentor untuk melihat detail lengkap.</li></ol><h2 id="mengajukan-permintaan-mentoring" tabindex="-1">Mengajukan Permintaan Mentoring <a class="header-anchor" href="#mengajukan-permintaan-mentoring" aria-label="Permalink to &quot;Mengajukan Permintaan Mentoring&quot;">​</a></h2><h3 id="sebelum-mengajukan" tabindex="-1">Sebelum Mengajukan <a class="header-anchor" href="#sebelum-mengajukan" aria-label="Permalink to &quot;Sebelum Mengajukan&quot;">​</a></h3><p>Pastikan Anda sudah masuk dan mengetahui mentor yang ingin dihubungi.</p><h3 id="mengirim-permintaan" tabindex="-1">Mengirim Permintaan <a class="header-anchor" href="#mengirim-permintaan" aria-label="Permalink to &quot;Mengirim Permintaan&quot;">​</a></h3><ol><li>Buka halaman detail mentor.</li><li>Klik tombol <strong>Ajukan Permintaan</strong>.</li><li>Tuliskan tujuan atau topik yang ingin dibahas.</li><li>Klik <strong>Kirim</strong>.</li><li>Permintaan akan berstatus <strong>Pending</strong> hingga disetujui mentor.</li></ol><h2 id="alur-status-permintaan" tabindex="-1">Alur Status Permintaan <a class="header-anchor" href="#alur-status-permintaan" aria-label="Permalink to &quot;Alur Status Permintaan&quot;">​</a></h2><p>Permintaan mentoring mengikuti alur berikut:</p><table tabindex="0"><thead><tr><th>Status</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Permintaan telah dikirim dan menunggu persetujuan mentor.</td></tr><tr><td><strong>Diterima</strong></td><td>Mentor menyetujui permintaan; proses bimbingan dapat dimulai.</td></tr><tr><td><strong>Selesai</strong></td><td>Proses bimbingan telah berakhir dan ditandai selesai.</td></tr></tbody></table><h3 id="meninjau-permintaan-untuk-mentor" tabindex="-1">Meninjau Permintaan (untuk Mentor) <a class="header-anchor" href="#meninjau-permintaan-untuk-mentor" aria-label="Permalink to &quot;Meninjau Permintaan (untuk Mentor)&quot;">​</a></h3><ol><li>Buka menu <strong>Mentoring</strong> lalu bagian permintaan masuk.</li><li>Lihat daftar permintaan yang berstatus <strong>Pending</strong>.</li><li>Klik <strong>Terima</strong> untuk menyetujui permintaan, atau <strong>Tolak</strong> jika tidak dapat melayani.</li><li>Permintaan yang diterima berpindah status menjadi <strong>Diterima</strong> dan dapat ditindaklanjuti.</li></ol><h3 id="menyelesaikan-bimbingan" tabindex="-1">Menyelesaikan Bimbingan <a class="header-anchor" href="#menyelesaikan-bimbingan" aria-label="Permalink to &quot;Menyelesaikan Bimbingan&quot;">​</a></h3><p>Setelah proses bimbingan selesai, permintaan dapat ditandai <strong>Selesai</strong> oleh mentor sehingga slot kapasitas kembali tersedia.</p><h2 id="mendaftar-sebagai-mentor" tabindex="-1">Mendaftar sebagai Mentor <a class="header-anchor" href="#mendaftar-sebagai-mentor" aria-label="Permalink to &quot;Mendaftar sebagai Mentor&quot;">​</a></h2><p>Pendaftaran mentor tersedia untuk <strong>alumni yang sudah masuk</strong> dan (disarankan) telah berpengalaman di bidangnya.</p><h3 id="membuka-formulir-pendaftaran" tabindex="-1">Membuka Formulir Pendaftaran <a class="header-anchor" href="#membuka-formulir-pendaftaran" aria-label="Permalink to &quot;Membuka Formulir Pendaftaran&quot;">​</a></h3><ol><li>Klik menu <strong>Mentoring</strong>.</li><li>Klik tombol <strong>Daftar sebagai Mentor</strong>.</li><li>Anda akan diarahkan ke halaman pendaftaran mentor.</li></ol><h3 id="mengisi-formulir" tabindex="-1">Mengisi Formulir <a class="header-anchor" href="#mengisi-formulir" aria-label="Permalink to &quot;Mengisi Formulir&quot;">​</a></h3><p>Isi informasi berikut:</p><ul><li><strong>Bidang keahlian</strong> yang dapat Anda bimbing.</li><li><strong>Deskripsi singkat</strong> pengalaman dan topik bimbingan.</li><li><strong>Kapasitas</strong> jumlah mentee yang dapat diterima.</li><li>Kontak yang dapat dihubungi.</li></ul><h3 id="menyimpan-profil-mentor" tabindex="-1">Menyimpan Profil Mentor <a class="header-anchor" href="#menyimpan-profil-mentor" aria-label="Permalink to &quot;Menyimpan Profil Mentor&quot;">​</a></h3><ol><li>Klik tombol <strong>Simpan</strong>.</li><li>Profil mentor Anda tampil di daftar mentor dan dapat dihubungi pengguna lain.</li></ol><h3 id="mengubah-atau-menonaktifkan-profil-mentor" tabindex="-1">Mengubah atau Menonaktifkan Profil Mentor <a class="header-anchor" href="#mengubah-atau-menonaktifkan-profil-mentor" aria-label="Permalink to &quot;Mengubah atau Menonaktifkan Profil Mentor&quot;">​</a></h3><ol><li>Buka halaman profil mentor Anda.</li><li>Gunakan tombol <strong>Ubah</strong> untuk memperbarui informasi.</li><li>Jika tidak lagi dapat melayani, nonaktifkan atau hapus profil mentor Anda.</li></ol><h2 id="tips-penggunaan" tabindex="-1">Tips Penggunaan <a class="header-anchor" href="#tips-penggunaan" aria-label="Permalink to &quot;Tips Penggunaan&quot;">​</a></h2><ul><li>Sebagai <strong>mentee</strong>: jelaskan dengan spesifik topik yang ingin dipelajari agar mentor mudah membantu.</li><li>Sebagai <strong>mentor</strong>: jaga kapasitas tetap realistis dan perbarui status permintaan secara rutin.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/referral">Sistem Referral</a> untuk meminta rekomendasi ke perusahaan tujuan.</p>',31)])])}const k=n(r,[["render",l]]);export{h as __pageData,k as default};
